'use strict';
// Supabase Storage (private bucket) via REST. Object paths are generated by the
// server and only short-lived signed URLs ever reach browsers.
// Docs: https://supabase.com/docs/reference/javascript/storage-from-createsignedurl

const { HttpError } = require('./http');

const BUCKET = () => process.env.SO_STORAGE_BUCKET || 'smooth-operators';

function base() {
  const url = process.env.SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) throw new HttpError(503, 'storage_not_configured', 'File storage is not configured yet.');
  return { url: url.replace(/\/+$/, ''), key };
}

function encPath(p) { return p.split('/').map(encodeURIComponent).join('/'); }

async function call(path, init) {
  const { url, key } = base();
  let res;
  try {
    res = await fetch(`${url}/storage/v1${path}`, {
      ...init,
      headers: { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json', ...(init.headers || {}) },
      signal: AbortSignal.timeout(10000),
    });
  } catch {
    throw new HttpError(503, 'storage_unreachable', 'File storage is temporarily unavailable. Please try again.');
  }
  const json = await res.json().catch(() => ({}));
  if (!res.ok) {
    console.error('[so] storage error', res.status, json && (json.error || json.statusCode));
    throw new HttpError(res.status === 404 || json.statusCode === '404' ? 404 : 503, 'storage_error', 'That file is not available right now.');
  }
  return { url, json };
}

async function signedDownloadUrl(objectPath, expiresIn, downloadName) {
  const { url, json } = await call(`/object/sign/${BUCKET()}/${encPath(objectPath)}`, {
    method: 'POST', body: JSON.stringify({ expiresIn }),
  });
  const rel = json.signedURL || json.signedUrl;
  if (!rel) throw new HttpError(503, 'storage_error', 'That file is not available right now.');
  let full = `${url}/storage/v1${rel.startsWith('/') ? '' : '/'}${rel}`;
  if (downloadName) full += `${full.includes('?') ? '&' : '?'}download=${encodeURIComponent(downloadName)}`;
  return full;
}

async function signedUploadUrl(objectPath) {
  const { url, json } = await call(`/object/upload/sign/${BUCKET()}/${encPath(objectPath)}`, { method: 'POST', body: '{}' });
  const rel = json.url;
  if (!rel) throw new HttpError(503, 'storage_error', 'Could not prepare the upload.');
  return `${url}/storage/v1${rel.startsWith('/') ? '' : '/'}${rel}`;
}

async function removeObjects(paths) {
  if (!paths.length) return;
  try {
    await call(`/object/${BUCKET()}`, { method: 'DELETE', body: JSON.stringify({ prefixes: paths }) });
  } catch (e) {
    console.error('[so] storage cleanup failed', e.code);
  }
}

const UPLOAD_RULES = {
  template: { mimes: ['application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    'application/msword', 'application/vnd.ms-excel', 'text/csv', 'text/plain'], max: 50 * 1024 * 1024 },
  practice: { mimes: ['audio/mpeg', 'audio/mp4', 'audio/x-m4a', 'audio/aac', 'audio/wav', 'audio/x-wav', 'video/mp4'], max: 500 * 1024 * 1024 },
  replay:   { mimes: ['video/mp4', 'audio/mpeg', 'audio/mp4', 'audio/x-m4a'], max: 500 * 1024 * 1024 },
  other:    { mimes: ['application/pdf', 'text/plain', 'image/jpeg', 'image/png', 'image/webp'], max: 50 * 1024 * 1024 },
  photo:    { mimes: ['image/jpeg', 'image/png', 'image/webp'], max: 5 * 1024 * 1024 },
};

function checkUpload(kind, mime, size) {
  const rule = UPLOAD_RULES[kind];
  if (!rule) throw new HttpError(400, 'invalid_input', 'Unknown upload type.');
  if (!rule.mimes.includes(mime)) throw new HttpError(400, 'invalid_file_type', `That file type isn’t supported here.`);
  if (!Number.isInteger(size) || size <= 0 || size > rule.max) {
    throw new HttpError(400, 'invalid_file_size', `Files must be under ${Math.round(rule.max / 1024 / 1024)} MB.`);
  }
}

function safeFileName(name) {
  const cleaned = String(name || 'file').normalize('NFKD').replace(/[^\w.\- ]+/g, '').replace(/\s+/g, '-').slice(0, 80);
  return cleaned || 'file';
}

module.exports = { signedDownloadUrl, signedUploadUrl, removeObjects, checkUpload, safeFileName, UPLOAD_RULES };
